What goes wrong with this example, and why is silently retaining one duplicate ID unsafe?

```python
def outline(records):
    nodes = {r['id']: {**r, 'children': []} for r in records}
    roots = []
    for node in nodes.values():
        if node['parent_id'] is None:
            roots.append(node)
        else:
            nodes[node['parent_id']]['children'].append(node)
    return roots

records = [
    {'id': 'a', 'parent_id': None, 'title': 'A'},
    {'id': 'b', 'parent_id': 'a', 'title': 'B'},
    {'id': 'b', 'parent_id': None, 'title': 'Other B'},
]
```

Create all nodes in the first pass, rejecting duplicate IDs. In the second pass, check that each non-null parent exists before attaching the node:

```python
def outline(records):
    nodes = {}
    for record in records:
        node_id = record['id']
        if node_id in nodes:
            raise ValueError(f"Duplicate ID: {node_id!r}")
        nodes[node_id] = {**record, 'children': []}

    roots = []
    for record in records:
        node = nodes[record['id']]
        parent_id = record['parent_id']
        if parent_id is None:
            roots.append(node)
        else:
            if parent_id not in nodes:
                raise ValueError(f"Missing parent ID: {parent_id!r}")
            nodes[parent_id]['children'].append(node)
    return roots
```

The second pass preserves input order for roots and siblings, including when a child precedes its parent. Cycle detection still needs separate validation; otherwise, cyclic nodes will not appear in the returned roots.

Walk each parent chain iteratively, keeping a set of IDs in the current chain and a set of IDs whose chains have already been validated. Reaching an ID in the current chain means a cycle; reaching a root or a completed ID means the whole current chain is valid. This checks disconnected cycles and self-cycles without rechecking completed chains.

```python
def outline(records):
    records = list(records)
    nodes = {}

    for record in records:
        node_id = record['id']
        if node_id is None:
            raise ValueError('None cannot be a record ID')
        if node_id in nodes:
            raise ValueError(f'Duplicate ID: {node_id!r}')
        nodes[node_id] = {**record, 'children': []}

    for record in records:
        parent_id = record['parent_id']
        if parent_id is not None and parent_id not in nodes:
            raise ValueError(f'Missing parent ID: {parent_id!r}')

    complete = set()
    for record in records:
        current = record['id']
        chain = set()
        while current is not None and current not in complete:
            if current in chain:
                raise ValueError(f'Cycle involving ID: {current!r}')
            chain.add(current)
            current = nodes[current]['parent_id']
        complete.update(chain)

    roots = []
    for record in records:
        node = nodes[record['id']]
        parent_id = record['parent_id']
        if parent_id is None:
            roots.append(node)
        else:
            nodes[parent_id]['children'].append(node)
    return roots
```

For a valid chain `c → b → a → None`, all three become complete. A later chain reaching `b` stops there. Each ID enters a newly validated chain at most once, so expected time is O(n) with standard hash-table assumptions; space is O(n), including the output and validation sets. The final pass preserves root and sibling input order.

```python
import unittest


def outline(records):
    records = list(records)
    nodes = {}
    for record in records:
        node_id = record['id']
        if node_id is None:
            raise ValueError('None cannot be a record ID')
        if node_id in nodes:
            raise ValueError(f'Duplicate ID: {node_id!r}')
        nodes[node_id] = {**record, 'children': []}

    for node in nodes.values():
        parent = node['parent_id']
        if parent is not None and parent not in nodes:
            raise ValueError(f'Missing parent ID: {parent!r}')

    complete = set()
    for node_id in nodes:
        current, chain = node_id, set()
        while current is not None and current not in complete:
            if current in chain:
                raise ValueError(f'Cycle involving ID: {current!r}')
            chain.add(current)
            current = nodes[current]['parent_id']
        complete.update(chain)

    roots = []
    for record in records:
        node = nodes[record['id']]
        parent = record['parent_id']
        if parent is None:
            roots.append(node)
        else:
            nodes[parent]['children'].append(node)
    return roots


class OutlineTests(unittest.TestCase):
    def test_order_and_child_before_parent(self):
        records = [
            {'id': 'c2', 'parent_id': 'p'},
            {'id': 'r', 'parent_id': None},
            {'id': 'c1', 'parent_id': 'p'},
            {'id': 'p', 'parent_id': None},
        ]
        roots = outline(iter(records))
        self.assertEqual([n['id'] for n in roots], ['r', 'p'])
        self.assertEqual([n['id'] for n in roots[1]['children']], ['c2', 'c1'])
        self.assertNotIn('children', records[0])

    def test_invalid_inputs(self):
        record = {'id': 'a', 'parent_id': None}
        cases = [
            [record, record.copy()],
            [{'id': None, 'parent_id': None}],
            [{'id': 'a', 'parent_id': 'missing'}],
            [{'id': 'a', 'parent_id': 'a'}],
            [record, {'id': 'b', 'parent_id': 'c'},
             {'id': 'c', 'parent_id': 'b'}],
        ]
        for records in cases:
            with self.subTest(records=records), self.assertRaises(ValueError):
                outline(records)

    def test_empty_and_deep(self):
        self.assertEqual(outline([]), [])
        records = [{'id': i, 'parent_id': i - 1 if i else None}
                   for i in range(5000)]
        node = outline(records)[0]
        for i in range(5000):
            self.assertEqual(node['id'], i)
            children = node['children']
            self.assertEqual(len(children), i < 4999)
            if children:
                node = children[0]


if __name__ == '__main__':
    unittest.main()
```

Expected time and space are O(n), assuming ordinary hash-table behavior. The function makes shallow copies of records and does not mutate the input. Tests are provided but have not been run.
